from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone, CommandFailure


class UtfLabController(GenericUnixCommand):
    """utf_lab-controller command class."""

    def __init__(self, connection, operation, wait=None, prompt=None, newline_chars=None, runner=None):
        """
        utf_lab-controller command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param operation: Allowed operations: start - start stopped UTF Lab containers
                                              stop - stop all UTF Lab containers
                                              restart - restart all UTF Lab containers
        :param wait: Optinal wait flag used with (re)start to block until UTF Lab API is listening
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(UtfLabController, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.operation = operation
        self.wait_option = wait
        self.success_lines = {'start': 'All UTF Lab containers started successfully.',
                              'stop': 'All UTF Lab containers stopped successfully.',
                              'restart': 'All UTF Lab containers restarted successfully.'}
        self.success_line_found = False
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"utf_lab-controller {self.operation}"
        if self.wait_option:
            cmd += ' --wait'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse output lines.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._find_success(line)
            except ParsingDone:
                pass
        return super(UtfLabController, self).on_new_line(line, is_full_line)

    def _find_success(self, line):
        if self.success_lines[self.operation] in line:
            self.success_line_found = True
            raise ParsingDone()

    @property
    def _is_done(self):
        return super(UtfLabController, self)._is_done

    @_is_done.setter
    def _is_done(self, value):
        if value is True and self.success_line_found is False:
            self._set_exception_without_done(CommandFailure(self, f"Success string '{self.success_lines[self.operation]}' not found in output."))
        super(UtfLabController, self.__class__)._is_done.fset(self, value)


